insert into public.sources (id, label, kind, url, license, terms, retrieved_at) values ('natural-earth-v5.1.2', 'Natural Earth 1:10m — populated places (v5.1.2)', 'open_data', 'https://github.com/nvkelso/natural-earth-vector', 'Domaine public', 'Réutilisation libre, y compris commerciale ; attribution « Made with Natural Earth » recommandée.', '2026-09-25') on conflict (id) do update set label = excluded.label, kind = excluded.kind, url = excluded.url, license = excluded.license, terms = excluded.terms, retrieved_at = excluded.retrieved_at;
insert into public.sources (id, label, kind, url, license, terms, retrieved_at) values ('horizon-editorial-2026-09', 'Rédaction HORIZON (démonstration)', 'editorial', null, 'Texte original du projet HORIZON (droits du porteur de projet)', 'Textes et estimations rédigés pour la démonstration, sans vérification sur place ni source officielle. À relire avant publication.', null) on conflict (id) do update set label = excluded.label, kind = excluded.kind, url = excluded.url, license = excluded.license, terms = excluded.terms, retrieved_at = excluded.retrieved_at;
insert into public.sources (id, label, kind, url, license, terms, retrieved_at) values ('horizon-demo-fixture', 'Fixture de démonstration HORIZON', 'demo_fixture', null, 'Contenu fictif original du projet HORIZON', 'Établissements, prix et horaires fictifs. Ne correspondent à aucun commerce réel.', null) on conflict (id) do update set label = excluded.label, kind = excluded.kind, url = excluded.url, license = excluded.license, terms = excluded.terms, retrieved_at = excluded.retrieved_at;
insert into public.destinations (id, name, region, country_code, locale, currency, timezone, center, center_source_id, bbox, tagline, description, palette, medal_title, medal_place_ids) values ('annecy', 'Annecy', 'Haute-Savoie, Auvergne-Rhône-Alpes', 'FR', 'fr-FR', 'EUR', 'Europe/Paris', extensions.st_setsrid(extensions.st_makepoint(6.1167, 45.9), 4326)::extensions.geography, 'natural-earth-v5.1.2', array[5.98, 45.76, 6.3, 45.96]::double precision[], 'Canaux, lac et sommets à portée de pas', 'Une vieille ville traversée de canaux, un lac aux eaux claires et des sommets accessibles en quelques minutes : Annecy se prête autant aux flâneries qu''aux sorties nature.', 'alpine', 'Le tour d''Annecy', array['annecy-palais-de-l-isle', 'annecy-chateau', 'annecy-jardins-de-l-europe', 'annecy-paquier', 'annecy-semnoz']::text[]) on conflict (id) do update set name = excluded.name, region = excluded.region, center = excluded.center, bbox = excluded.bbox, tagline = excluded.tagline, description = excluded.description, palette = excluded.palette, medal_title = excluded.medal_title, medal_place_ids = excluded.medal_place_ids;
insert into public.destinations (id, name, region, country_code, locale, currency, timezone, center, center_source_id, bbox, tagline, description, palette, medal_title, medal_place_ids) values ('lyon', 'Lyon', 'Rhône, Auvergne-Rhône-Alpes', 'FR', 'fr-FR', 'EUR', 'Europe/Paris', extensions.st_setsrid(extensions.st_makepoint(4.8281, 45.772), 4326)::extensions.geography, 'natural-earth-v5.1.2', array[4.76, 45.71, 4.9, 45.8]::double precision[], 'Deux collines, deux fleuves, mille tables', 'Entre Rhône et Saône, Lyon superpose ses vestiges antiques, son quartier Renaissance et sa réputation gourmande. Une ville qui se découvre à pied, par ses passages et ses hauteurs.', 'lyon', 'Lyon, des Romains aux canuts', array['lyon-fourviere', 'lyon-theatres-romains', 'lyon-vieux-lyon', 'lyon-mur-des-canuts', 'lyon-halles-bocuse']::text[]) on conflict (id) do update set name = excluded.name, region = excluded.region, center = excluded.center, bbox = excluded.bbox, tagline = excluded.tagline, description = excluded.description, palette = excluded.palette, medal_title = excluded.medal_title, medal_place_ids = excluded.medal_place_ids;
insert into public.destinations (id, name, region, country_code, locale, currency, timezone, center, center_source_id, bbox, tagline, description, palette, medal_title, medal_place_ids) values ('marseille', 'Marseille', 'Bouches-du-Rhône, Provence-Alpes-Côte d''Azur', 'FR', 'fr-FR', 'EUR', 'Europe/Paris', extensions.st_setsrid(extensions.st_makepoint(5.3731, 43.2919), 4326)::extensions.geography, 'natural-earth-v5.1.2', array[5.28, 43.19, 5.5, 43.33]::double precision[], 'Lumière, calcaire et Méditerranée', 'Port millénaire tourné vers la Méditerranée, Marseille mêle quartiers populaires, forts, collines et calanques. Une ville de contrastes où la mer n''est jamais loin.', 'mediterranee', 'Marseille, de la Bonne Mère aux calanques', array['marseille-notre-dame-de-la-garde', 'marseille-vieux-port', 'marseille-panier', 'marseille-mucem', 'marseille-vallon-des-auffes']::text[]) on conflict (id) do update set name = excluded.name, region = excluded.region, center = excluded.center, bbox = excluded.bbox, tagline = excluded.tagline, description = excluded.description, palette = excluded.palette, medal_title = excluded.medal_title, medal_place_ids = excluded.medal_place_ids;
insert into public.destinations (id, name, region, country_code, locale, currency, timezone, center, center_source_id, bbox, tagline, description, palette, medal_title, medal_place_ids) values ('la-rochelle', 'La Rochelle', 'Charente-Maritime, Nouvelle-Aquitaine', 'FR', 'fr-FR', 'EUR', 'Europe/Paris', extensions.st_setsrid(extensions.st_makepoint(-1.15, 46.1667), 4326)::extensions.geography, 'natural-earth-v5.1.2', array[-1.26, 46.12, -1.1, 46.19]::double precision[], 'Tours de pierre et air du large', 'Gardé par ses tours médiévales, le Vieux-Port de La Rochelle ouvre sur l''Atlantique. Arcades, parcs et plages composent une ville maritime facile à parcourir à pied ou à vélo.', 'atlantique', 'La Rochelle, du port au large', array['la-rochelle-tours', 'la-rochelle-lanterne', 'la-rochelle-vieux-port', 'la-rochelle-grosse-horloge', 'la-rochelle-parc-charruyer']::text[]) on conflict (id) do update set name = excluded.name, region = excluded.region, center = excluded.center, bbox = excluded.bbox, tagline = excluded.tagline, description = excluded.description, palette = excluded.palette, medal_title = excluded.medal_title, medal_place_ids = excluded.medal_place_ids;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-palais-de-l-isle', 'annecy', 'Palais de l''Isle', 'historic', array['heritage', 'culture']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(6.1286, 45.899), 4326)::extensions.geography, 'approximate', '881f912a5bfffff', 8, 'L''édifice en proue sur le canal du Thiou, emblème de la vieille ville.', 'Posé sur un îlot au milieu du canal du Thiou, ce bâtiment de pierre à la silhouette de navire est l''image la plus connue d''Annecy. Ses abords se découvrent librement depuis les quais ; l''intérieur accueille un espace consacré au patrimoine local.', 'Construit au Moyen Âge, l''édifice a connu plusieurs usages au fil des siècles, dont celui de prison. Il est aujourd''hui un lieu de visite patrimonial.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":45,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"canal","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-chateau', 'annecy', 'Château d''Annecy', 'museum', array['heritage', 'culture']::text[], 'indoor', extensions.st_setsrid(extensions.st_makepoint(6.1262, 45.898), 4326)::extensions.geography, 'approximate', '881f912a51fffff', 8, 'Ancienne demeure des comtes de Genève dominant la vieille ville.', 'Le château surplombe les toits de la vieille ville. Il abrite aujourd''hui un musée et offre, depuis ses terrasses, une vue dégagée sur les canaux et le lac.', 'Résidence seigneuriale au Moyen Âge, le château a été transformé au cours des siècles avant de devenir un musée.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":90,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"castle","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_