insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-jardins-de-l-europe', 'annecy', 'Jardins de l''Europe et pont des Amours', 'park', array['nature', 'relax']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(6.1336, 45.9007), 4326)::extensions.geography, 'approximate', '881f91212dfffff', 8, 'Un parc arboré au bord du lac, relié au Pâquier par un petit pont.', 'Grands arbres, pelouses et vue sur les montagnes : ce jardin au bord de l''eau invite à la pause. Le pont qui enjambe le canal du Vassé est l''un des points de vue les plus photographiés de la ville.', null, false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":40,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"garden","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-paquier', 'annecy', 'Le Pâquier, rive du lac', 'lake', array['nature', 'relax', 'family']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(6.1365, 45.9025), 4326)::extensions.geography, 'approximate', '881f91212dfffff', 8, 'La grande pelouse face au lac, pour contempler les montagnes.', 'Vaste esplanade gazonnée ouverte sur le lac, le Pâquier est le lieu de rendez-vous des promeneurs. On y observe les sommets qui ferment l''horizon et les bateaux qui quittent le port.', null, false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":45,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"lake","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, sour