insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-basilique-visitation', 'annecy', 'Basilique de la Visitation', 'religious', array['heritage', 'culture']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(6.1219, 45.8964), 4326)::extensions.geography, 'approximate', '881f912a51fffff', 8, 'Une basilique sur les hauteurs, avec un large panorama sur la ville.', 'Sur les pentes qui dominent Annecy, la basilique offre un moment de calme et une vue étendue sur la ville et le lac. Un lieu de culte : tenue et silence de rigueur pendant les offices.', 'Édifice du XXe siècle lié à l''histoire de l''ordre de la Visitation, fondé à Annecy au XVIIe siècle.', true, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":30,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"church","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-semnoz', 'annecy', 'Le Semnoz, crêt de Châtillon', 'viewpoint', array['nature', 'sport']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(6.0935, 45.7755), 4326)::extensions.geography, 'approximate', '881f912915fffff', 8, 'Montagne voisine d''Annecy, panorama des Alpes par temps clair.', 'Au-dessus du lac, le Semnoz offre des alpages et des sentiers faciles d''accès. Par temps dégagé, le regard porte loin sur les massifs alpins. Prévoir des vêtements chauds : la température baisse vite en altitude.', null, false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":150,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"difficulty":{"status":"estimate","value":{"level":"moderate"},"note":"Niveau estimé — consulter un itinéraire officiel et la météo avant de partir."},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"summit","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-gorges-du-fier', 'annecy', 'Gorges du Fier', 'hike', array['nature', 'family']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(6.0375, 45.9078), 4326)::extensions.geography, 'approximate', '881f9139d1fffff', 8, 'Une passerelle au fond d''un étroit canyon creusé par la rivière.', 'À quelques kilomètres d''Annecy, une passerelle accrochée à la roche longe le Fier au fond de gorges étroites. Une sortie rafraîchissante, à vérifier selon la saison d''ouverture.', null, true, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":75,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"difficulty":{"status":"estimate","value":{"level":"easy"},"note":"Niveau estimé — vérifier les conditions d''accès."},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"gorge","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('annecy-talloires', 'annecy', 'Talloires et sa baie', 'lake', array['nature', 'relax']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(6.213, 45.8411), 4326)::extensions.geography, 'approximate', '881f912ab7fffff', 8, 'Un village de la rive est, entre eaux turquoise et falaises.', 'Sur la rive est du lac, Talloires s''étire autour d''une baie abritée. Un bon point de départ pour une balade au bord de l''eau, loin de l''agitation du centre-ville.', null, true, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":90,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"bay","palette":"alpine"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, ve