insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-fourviere', 'lyon', 'Basilique Notre-Dame de Fourvière', 'religious', array['heritage', 'culture']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(4.8224, 45.7622), 4326)::extensions.geography, 'approximate', '881f902091fffff', 8, 'La basilique blanche qui veille sur Lyon depuis sa colline.', 'Au sommet de la colline de Fourvière, la basilique domine la ville. Son esplanade offre l''un des plus beaux panoramas sur Lyon, les toits du Vieux Lyon et, par temps clair, les Alpes au loin.', 'Édifiée à la fin du XIXe siècle, elle est devenue l''un des symboles de la ville.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":60,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"basilica","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = 