insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-theatres-romains', 'lyon', 'Théâtres romains de Fourvière', 'historic', array['heritage', 'culture']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(4.8196, 45.7597), 4326)::extensions.geography, 'approximate', '881f902095fffff', 8, 'Les gradins antiques de Lugdunum, à flanc de colline.', 'Vestiges de l''ancienne Lugdunum, un grand théâtre et un odéon s''étagent sur la colline. Le site permet d''imaginer la ville romaine qui fut l''une des plus importantes de Gaule.', 'Les théâtres datent de l''époque romaine, lorsque Lugdunum était une capitale administrative de la Gaule.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":60,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"amphitheatre","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, 