insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-vieux-lyon', 'lyon', 'Vieux Lyon et ses traboules', 'historic', array['heritage', 'culture']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(4.8272, 45.7625), 4326)::extensions.geography, 'approximate', '881f902091fffff', 8, 'Ruelles Renaissance et passages secrets entre les immeubles.', 'Au pied de Fourvière, le quartier Renaissance aligne façades colorées, cours intérieures et traboules, ces passages qui relient une rue à l''autre à travers les immeubles. Certaines traboules sont des parties privées : respecter les habitants et les horaires d''accès.', 'Le quartier s''est développé à la Renaissance, lorsque Lyon était une place marchande et bancaire majeure.', false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":90,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"old-town","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, d