insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-tete-d-or', 'lyon', 'Parc de la Tête d''Or', 'park', array['nature', 'relax', 'family']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(4.8522, 45.7772), 4326)::extensions.geography, 'approximate', '881f902549fffff', 8, 'Le grand parc urbain de Lyon, son lac et ses serres.', 'Allées ombragées, lac, roseraie et grandes pelouses : le parc est une respiration au cœur de la ville, idéale pour une pause en famille ou une promenade à deux.', 'Aménagé au XIXe siècle, il compte parmi les grands parcs urbains de France.', false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":90,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"garden","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded