insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-confluences', 'lyon', 'Musée des Confluences', 'museum', array['culture', 'family']::text[], 'indoor', extensions.st_setsrid(extensions.st_makepoint(4.818, 45.7326), 4326)::extensions.geography, 'approximate', '881f9020b7fffff', 8, 'Sciences et sociétés dans un vaisseau de verre et d''acier.', 'À la pointe où se rejoignent le Rhône et la Saône, ce musée à l''architecture spectaculaire explore l''histoire de la Terre, du vivant et des sociétés humaines.', null, false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":120,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"modern","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional = excluded.fictional, sponsored = excluded.sponsored;
