insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('lyon-mur-des-canuts', 'lyon', 'Croix-Rousse et mur des Canuts', 'monument', array['culture', 'heritage']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(4.8285, 45.7706), 4326)::extensions.geography, 'approximate', '881f902099fffff', 8, 'Une immense fresque en trompe-l''œil sur la colline des tisseurs.', 'Sur la colline de la Croix-Rousse, quartier historique des canuts (ouvriers de la soie), une fresque monumentale en trompe-l''œil raconte la vie du quartier. Les pentes voisines se découvrent par leurs escaliers et leurs traboules.', 'La Croix-Rousse fut au XIXe siècle le cœur de l''industrie de la soie lyonnaise.', true, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":45,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"mural","palette":"lyon"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.h