insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-notre-dame-de-la-garde', 'marseille', 'Notre-Dame de la Garde', 'religious', array['heritage', 'culture']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(5.3712, 43.284), 4326)::extensions.geography, 'approximate', '8839681527fffff', 8, 'La « Bonne Mère » et le plus vaste panorama sur Marseille.', 'Perchée sur la plus haute colline de la ville, la basilique veille sur Marseille et la mer. De son parvis, la vue embrasse le Vieux-Port, les îles du Frioul et les collines alentour.', 'Construite au XIXe siècle à l''emplacement d''un ancien fort et d''une chapelle plus ancienne.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":75,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"basilica","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = exclud