insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-vieux-port', 'marseille', 'Vieux-Port', 'historic', array['heritage', 'relax']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(5.3745, 43.2951), 4326)::extensions.geography, 'approximate', '883968152bfffff', 8, 'Le cœur battant de la ville, entre forts et quais animés.', 'Le port historique, encadré par deux forts, reste le centre de la vie marseillaise : marché aux poissons le matin, promeneurs et navettes maritimes tout au long de la journée.', 'Le site est le berceau de Marseille, fondée par des marins grecs dans l''Antiquité.', false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":45,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"harbour","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded