insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-mucem', 'marseille', 'MuCEM et fort Saint-Jean', 'museum', array['culture', 'heritage']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(5.361, 43.2968), 4326)::extensions.geography, 'approximate', '8839681529fffff', 8, 'Les civilisations de la Méditerranée, reliées à un fort historique.', 'Un musée contemporain à la résille de béton, relié par une passerelle au fort Saint-Jean. Même sans entrer dans les expositions, les jardins et les remparts offrent une promenade face à la mer.', null, false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":120,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"modern","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, verification = excluded.verification, fictional =