insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-panier', 'marseille', 'Le Panier', 'historic', array['heritage', 'culture']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(5.369, 43.299), 4326)::extensions.geography, 'approximate', '883968152bfffff', 8, 'Le plus ancien quartier de Marseille, ses escaliers et ses placettes.', 'Ruelles en pente, façades colorées, ateliers et placettes : le Panier se parcourt sans itinéraire précis. La Vieille Charité, ancien hospice, en est l''un des repères.', 'Quartier historique situé sur le site de la cité antique.', false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":75,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"old-town","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = e