insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-sugiton', 'marseille', 'Calanque de Sugiton', 'hike', array['nature', 'sport']::text[], 'outdoor', extensions.st_setsrid(extensions.st_makepoint(5.459, 43.2125), 4326)::extensions.geography, 'approximate', '883968009bfffff', 8, 'Une descente dans le massif jusqu''à une crique aux eaux claires.', 'Dans le Parc national des Calanques, un sentier caillouteux descend vers une crique encadrée de falaises. Chaussures fermées et eau indispensables. L''accès aux massifs peut être restreint en été selon le risque d''incendie : vérifier avant de partir.', null, false, '{"price":{"status":"estimate","value":{"kind":"free"},"note":"Espace public en accès libre — estimation éditoriale, non vérifiée."},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":180,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"difficulty":{"status":"estimate","value":{"level":"moderate"},"note":"Niveau estimé — dénivelé à la remontée ; consulter les informations officielles du parc."},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"calanque","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = e