insert into public.places (id, destination_id, name, category, themes, setting, location, location_precision, h3_cell, h3_res, summary, description, history, lesser_known, practical, restaurant, art, source_ids, verification, fictional, sponsored, status) values ('marseille-chateau-d-if', 'marseille', 'Château d''If', 'historic', array['heritage', 'culture']::text[], 'mixed', extensions.st_setsrid(extensions.st_makepoint(5.325, 43.2798), 4326)::extensions.geography, 'approximate', '8839680255fffff', 8, 'La forteresse insulaire rendue célèbre par la littérature.', 'Sur un îlot face à la ville, cette forteresse accessible en bateau a inspiré un célèbre roman d''aventures. La traversée fait partie de l''expérience ; elle dépend de la météo en mer.', 'Forteresse royale du XVIe siècle, elle servit ensuite de prison.', false, '{"price":{"status":"unknown"},"openingHours":{"status":"unknown"},"visitMinutes":{"status":"estimate","value":150,"note":"Durée conseillée — estimation éditoriale."},"accessibility":{"status":"unknown"},"booking":{"status":"unknown"},"website":{"status":"unknown"}}'::jsonb, null, '{"motif":"island-fort","palette":"mediterranee"}'::jsonb, array['horizon-editorial-2026-09']::text[], '{"status":"unverified","checkedAt":null,"note":"Lieu réel cité à titre de démonstration : coordonnées approximatives, texte éditorial non relu, informations pratiques à vérifier."}'::jsonb, false, null, 'published') on conflict (id) do update set destination_id = excluded.destination_id, name = excluded.name, category = excluded.category, themes = excluded.themes, setting = excluded.setting, location = excluded.location, location_precision = excluded.location_precision, h3_cell = excluded.h3_cell, h3_res = excluded.h3_res, summary = excluded.summary, description = excluded.description, history = excluded.history, lesser_known = excluded.lesser_known, practical = excluded.practical, restaurant = excluded.restaurant, art = excluded.art, source_ids = excluded.source_ids, ver